// A Blitz tower round on a real map, worked out from real data.
//
// The map data (lib/tournament/towerMaps/<map>.json) is generated by the plugin
// repo's blitz_kit/generators/site_map.py: the floor is the map's nav mesh seen
// from above, the tower spots are the site's plant spots, the spawns are the ones
// the server uses (R5eGames.Tournament/tower_spawns), and every route is the nav
// mesh's walking path from a spawn to a tower spot, pulled tight, with the time it
// takes at rifle speed. Nothing here is drawn by hand.
//
// The rules are the plugin's, from R5eGames.Tournament.Core/Match/TowerRound.cs
// and Match/TowerController.cs. Keep these numbers in step with those files.

import dust2 from "./towerMaps/de_dust2.json";

/** Round length before anybody activates the tower (t_tower_round_seconds). */
export const ROUND_SECONDS = 75;
/** Holding E at the tower, everybody but the Engineer. */
export const ACTIVATE_SECONDS = 3;
/** Holding E at the tower, the Engineer. */
export const ENGINEER_SECONDS = 1.5;
/** What is left on the clock after the first activation. Takeovers do not add any. */
export const FINAL_SECONDS = 20;

export type Side = "t" | "ct";
export type Group = "t" | "ct" | "roamer";

export type MapPoint = { name: string; role: string | null; x: number; y: number; yaw: number };
export type MapRoute = { d: string; len: number; secs: number };
export type MapSite = {
  site: "A" | "B";
  /** x, y, width, height in SVG units: everything this site's rounds use. */
  view: number[];
  spots: MapPoint[];
  t: MapPoint[];
  ct: MapPoint[];
  roamer: MapPoint[];
  /** routes[spot][group][spawn index in that group] */
  routes: Record<Group, MapRoute[]>[];
};
export type TowerMap = {
  map: string;
  scale: number;
  run: number;
  bounds: number[];
  floor: string;
  upper: string;
  labels: { name: string; x: number; y: number; size: number }[];
  sites: MapSite[];
};

export const TOWER_MAPS: Record<string, TowerMap> = {
  de_dust2: dust2 as TowerMap,
};

export const needFor = (role: string | null) => (role === "engineer" ? ENGINEER_SECONDS : ACTIVATE_SECONDS);

/** A player in a scenario: runs a route, then maybe holds E, maybe is caught. */
export type Actor = {
  group: Group;
  /** Index into the site's spawns of that group, and into routes[spot][group]. */
  index: number;
  side: Side;
  role: string;
  from: string;
  arrive: number;
  holds: { from: number; to: number; need: number; done: boolean }[];
  /** Taken out at this time (the Roamer's duel), if at all. */
  out?: number;
};

export type Step = { at: number | null; key: string; vars?: Record<string, string | number> };

export type Scenario = {
  id: ScenarioId;
  actors: Actor[];
  /** Ownership changes, in order. */
  captures: { at: number; side: Side }[];
  /** Simulated seconds the scenario runs for. */
  end: number;
  /** Playback speed: the stand-off fast-forwards its 75 seconds. */
  speed: number;
  steps: Step[];
  outcome: Step;
};

export const SCENARIOS = ["race", "takeover", "roamer", "standoff"] as const;
export type ScenarioId = (typeof SCENARIOS)[number];

const r1 = (n: number) => Math.round(n * 10) / 10;
const other = (s: Side): Side => (s === "t" ? "ct" : "t");

/** The player of a group who would have the tower activated soonest, running and holding. */
function quickest(site: MapSite, spot: number, group: Group, side: Side): Actor {
  const routes = site.routes[spot][group];
  const people = site[group];
  let best = 0;
  let bestDone = Infinity;
  people.forEach((p, i) => {
    const done = routes[i].secs + needFor(p.role);
    if (done < bestDone) {
      best = i;
      bestDone = done;
    }
  });
  const p = people[best];
  return { group, index: best, side, role: p.role ?? (side === "t" ? "rifler" : "frontrunner"), from: p.name, arrive: routes[best].secs, holds: [] };
}

/** The first activation, both teams sprinting from freeze time. */
function raceCore(site: MapSite, spot: number) {
  const t = quickest(site, spot, "t", "t");
  const ct = quickest(site, spot, "ct", "ct");
  const tDone = t.arrive + needFor(t.role);
  const ctDone = ct.arrive + needFor(ct.role);
  const winner: Side = tDone < ctDone ? "t" : "ct";
  const at = r1(Math.min(tDone, ctDone));
  const [win, lose] = winner === "t" ? [t, ct] : [ct, t];
  win.holds.push({ from: win.arrive, to: at, need: needFor(win.role), done: true });
  if (lose.arrive < at) lose.holds.push({ from: lose.arrive, to: at, need: needFor(lose.role), done: false });
  return { t, ct, win, lose, winner, at, margin: r1(Math.abs(tDone - ctDone)) };
}

const arriveStep = (a: Actor): Step => ({
  at: r1(a.arrive),
  key: "home.round.step.arrive",
  vars: { role: a.role, from: a.from, need: needFor(a.role) },
});

export function scenario(map: TowerMap, siteIndex: number, spot: number, id: ScenarioId): Scenario {
  const site = map.sites[siteIndex];
  const spotName = site.spots[spot].name;
  const start: Step = { at: 0, key: "home.round.step.start", vars: { spot: spotName } };

  if (id === "race" || id === "takeover") {
    const { win, lose, winner, at, margin } = raceCore(site, spot);
    const steps: Step[] = [start, ...[win, lose].map(arriveStep).sort((a, b) => (a.at ?? 0) - (b.at ?? 0))];
    steps.push({ at, key: "home.round.step.capture", vars: { team: winner } });
    if (lose.holds.length) steps.push({ at, key: "home.round.step.cut", vars: { role: lose.role } });
    const captures = [{ at, side: winner }];

    if (id === "race") {
      return {
        id, actors: [win, lose], captures, end: at + 2.5, speed: 1, steps,
        outcome: { at: null, key: "home.round.out.race", vars: { team: winner, role: win.role, at, margin } },
      };
    }

    // The side that lost the race goes again from zero, and the clock keeps running.
    const from = r1(Math.max(lose.arrive, at));
    const to = r1(from + needFor(lose.role));
    lose.holds.push({ from, to, need: needFor(lose.role), done: true });
    captures.push({ at: to, side: other(winner) });
    const left = r1(FINAL_SECONDS - (to - at));
    steps.push({ at: from, key: "home.round.step.again", vars: { role: lose.role, need: needFor(lose.role) } });
    steps.push({ at: to, key: "home.round.step.takeover", vars: { team: other(winner), left } });
    steps.push({ at: null, key: "home.round.step.zero" });
    return {
      id, actors: [win, lose], captures, end: to + 2.5, speed: 1, steps,
      outcome: { at: null, key: "home.round.out.takeover", vars: { left } },
    };
  }

  if (id === "roamer") {
    const t = quickest(site, spot, "t", "t");
    const routes = site.routes[spot].roamer;
    let ri = 0;
    routes.forEach((r, i) => { if (r.secs < routes[ri].secs) ri = i; });
    const roamer: Actor = {
      group: "roamer", index: ri, side: "ct", role: "roamer", from: site.roamer[ri].name, arrive: routes[ri].secs, holds: [],
    };
    const tDone = t.arrive + needFor(t.role);
    const steps: Step[] = [
      start,
      { at: 0, key: "home.round.step.hidden", vars: { from: roamer.from } },
    ];
    const captures: { at: number; side: Side }[] = [];
    // The duel: the Roamer is at the tower before the T has it, or arrives behind
    // a T who already does. Either way it is a duel the Roamer starts with the angle.
    const duel = r1(Math.max(roamer.arrive, t.arrive) + 0.4);
    if (roamer.arrive < tDone) {
      if (t.arrive < duel) t.holds.push({ from: t.arrive, to: Math.min(duel, tDone), need: needFor(t.role), done: false });
      t.out = duel;
      steps.push({ at: r1(roamer.arrive), key: "home.round.step.flank" });
      steps.push(arriveStep(t));
      steps.sort((a, b) => (a.at ?? 0) - (b.at ?? 0));
      steps.push({ at: duel, key: "home.round.step.caught", vars: { role: t.role } });
    } else {
      t.holds.push({ from: t.arrive, to: r1(tDone), need: needFor(t.role), done: true });
      captures.push({ at: r1(tDone), side: "t" });
      t.out = duel;
      steps.push(arriveStep(t));
      steps.push({ at: r1(tDone), key: "home.round.step.capture", vars: { team: "t" } });
      steps.push({ at: r1(roamer.arrive), key: "home.round.step.behind" });
      steps.push({ at: duel, key: "home.round.step.caught", vars: { role: t.role } });
    }
    const to = r1(duel + ACTIVATE_SECONDS);
    roamer.holds.push({ from: duel, to, need: ACTIVATE_SECONDS, done: true });
    captures.push({ at: to, side: "ct" });
    steps.push(captures.length > 1
      ? { at: to, key: "home.round.step.takeover", vars: { team: "ct", left: r1(FINAL_SECONDS - (to - captures[0].at)) } }
      : { at: to, key: "home.round.step.capture", vars: { team: "ct" } });
    return {
      id, actors: [t, roamer], captures, end: to + 2.5, speed: 1, steps,
      outcome: { at: null, key: "home.round.out.roamer", vars: { from: roamer.from, secs: r1(roamer.arrive) } },
    };
  }

  // The stand-off: nobody commits, and the clock runs out.
  return {
    id, actors: [], captures: [], end: ROUND_SECONDS, speed: 25,
    steps: [
      start,
      { at: null, key: "home.round.step.wait" },
      { at: ROUND_SECONDS, key: "home.round.step.runout" },
      { at: ROUND_SECONDS, key: "home.round.step.draw" },
    ],
    outcome: { at: null, key: "home.round.out.standoff" },
  };
}

/** Seconds on the round clock at simulated time `t`. */
export function clockAt(s: Scenario, t: number): number {
  const first = s.captures.find((c) => c.at <= t);
  if (!first) return Math.max(0, ROUND_SECONDS - t);
  return Math.max(0, FINAL_SECONDS - (t - first.at));
}

/** Who holds the tower at `t`, or null while it is dormant. */
export function ownerAt(s: Scenario, t: number): Side | null {
  let owner: Side | null = null;
  for (const c of s.captures) if (c.at <= t) owner = c.side;
  return owner;
}

export const formatClock = (secs: number) => {
  const s = Math.ceil(secs - 1e-6);
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
};

/** A route's polyline, for moving a player along it without the DOM. */
export function polyline(d: string) {
  const pts = d.slice(1).split("L").map((p) => p.trim().split(/\s+/).map(Number) as [number, number]);
  const acc = [0];
  for (let i = 1; i < pts.length; i++) acc.push(acc[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]));
  return { pts, acc, total: acc[acc.length - 1] };
}

export function pointAlong(line: ReturnType<typeof polyline>, frac: number): [number, number] {
  const f = Math.min(1, Math.max(0, frac));
  const want = f * line.total;
  let i = 1;
  while (i < line.acc.length - 1 && line.acc[i] < want) i++;
  const seg = line.acc[i] - line.acc[i - 1] || 1;
  const k = (want - line.acc[i - 1]) / seg;
  const [x0, y0] = line.pts[i - 1];
  const [x1, y1] = line.pts[Math.min(i, line.pts.length - 1)];
  return [x0 + (x1 - x0) * k, y0 + (y1 - y0) * k];
}
